# -*- coding: utf-8 -*-
"""k3: стабы и довески — resolution: restore/prefix/lead(точечные) + lead-остатки П4 (из p6_k3_leads_draft.json) + year."""
import json, re
cat = json.load(open('state/catalog_f5_k2.json', encoding='utf-8'))
def L(v): return json.load(open(f'work/{v}_lines.json', encoding='utf-8'))
v1, v5, v9, v10, v11, v12 = L('v1'), L('v5'), L('v9'), L('v10'), L('v11'), L('v12')
def ln(LL, i): return LL[i][1].strip()
def dehyph(s): return re.sub(r'([а-яё])- ([а-яё])', r'\1\2', s)
SET = {}
def restore(c, text, vol, lines, note):
    text = re.sub(r'\s+', ' ', text).strip()
    SET[str(c)] = {'field': 'annotation', 'before': cat[c]['annotation'], 'after': text, 'vol': vol, 'line': lines, 'class': 'restore', 'note': note}
# ── RESTORE: аннотации соседа −1 (вето П5-1 §5) ──
restore(5542, ln(v11, 171), 'v11', [171], 'сдвиг −1: каталожная аннотация = проза статьи cat5541 «Будьте готовы, Ваше высочество»; собственная проза статьи v11 @171 verbatim')
restore(5555, ln(v11, 284) + ' ' + ln(v11, 285), 'v11', [284, 285], 'сдвиг −1: каталожная аннотация = проза статьи cat5554 «Дачный домик для одной семьи» (+хвост); собственная проза v11 @284–285 verbatim')
restore(5716, ln(v11, 1792), 'v11', [1792], 'сдвиг −1: каталожная аннотация = лид-ансамбль + проза статьи cat5715 «Весенняя олимпиада, или Начальник хора»; собственная проза v11 @1792 verbatim (призовой блок @1793 не включён)')
restore(5980, ln(v12, 995), 'v12', [995], 'сдвиг −1: каталожная аннотация = список ролей + проза статьи cat5979 «Однажды двадцать лет спустя»; собственная проза v12 @995 verbatim')
# ── RESTORE: титровые обрывки вместо прозы ──
t753 = ln(v1, 5114) + ' ' + ln(v1, 5115).replace('■', '') + ' Фильм не сохранился.'
restore(753, t753, 'v1', [5114, 5115, 5116], 'аннотация = обрывок титров (@5112 «…худ. И. Мах лис, Б. Дубровский-Эшкс; ассист. реж. В. Браун»); проза статьи v1 @5114–5115 verbatim (снят одиночный OCR-глиф «■»), формула @5116 «Фильм нс сохранился.» — OCR «нс» приведено к формуле тома «не» (пометка)')
restore(5246, ln(v10, 460) + ' ' + ln(v10, 461), 'v10', [460, 461], 'аннотация = обрывок титров (@456 «…ассист. реж. С. Габисония, Н. Кутателадзе; ассист. опер. …»); проза статьи v10 @460–461 verbatim (призовые блоки @462–464 не включены)')
# ── RESTORE: киноальманах «Товарищ песня» (интро + новеллы; титры новелл не включены) ──
t3873 = ' '.join([ln(v5, 1009),
                  'Песня—пароль.', ln(v5, 1012),
                  'Песня о матери.', ln(v5, 1015),
                  'Песня на рассвете.', ln(v5, 1018) + ' ' + ln(v5, 1019)])
restore(3873, t3873, 'v5', [1009, 1010, 1012, 1013, 1015, 1016, 1018, 1019], 'аннотация = обрывок титров (@1007); восстановлено по структуре альманаха: интро @1009 + названия новелл (@1010, @1013, @1016 — до «Реж.-пост.») + проза новелл @1012, @1015, @1018–1019 verbatim; титры и «В ролях» новелл не включены')
# ── RESTORE: «Красная скрипка» (лид-остаток без прозы) ──
restore(4951, ln(v9, 598), 'v9', [598], 'аннотация = оркестр/соло/дубляж без прозы; проза статьи v9 @598 verbatim')
# ── RESTORE: «В городе «С»» — печатно только формула источника ──
restore(3774, 'По рассказу А. П. Чехова «Ионыч».', 'v5', [195], 'аннотация = список ролей + формула «Ло рассказу А. П. Чехова «Ионыч»» (OCR Л←П, @195); сюжетной прозы в томе нет; остаток < 40 знаков → точечно: формула по печати с исправленным OCR-глифом (пометка)')
# ── PREFIX: повреждённые формулы (утраченное начало по печати) ──
for c, pre, vol, lines, note in [
    (349, 'Уча', 'v1', [2368, 2369], 'повреждённая формула: каталожное «стие комсомольцев…» = печатное «Участие комсомольцев в обороне Петрограда…» (v1 @2368); восстановлен утраченный префикс «Уча»'),
    (3773, 'Экранизация одноименного романа А. Головко о том, как боец революции Давид Мот', 'v5', [185], 'повреждённая формула: каталожное «узка, возвратившись…» = печатное «Экранизация одноименного романа А. Головко о том, как боец революции Давид Мотузка, возвратившись…» (v5 @185); восстановлен утраченный префикс'),
]:
    b = cat[c]['annotation']
    SET[str(c)] = {'field': 'annotation', 'before': b, 'after': pre + b, 'vol': vol, 'line': lines, 'class': 'prefix', 'note': note}
# ── LEAD: cat5541 (резидуальный лид, вето П5-1 §5.2) ──
b = cat[5541]['annotation']; lead = 'ВЭ 1.1979 г. В съемках принимали участие школьники интерната № 1 г. Севастополя. '
assert b.startswith(lead)
SET['5541'] = {'field': 'annotation', 'before': b, 'after': b[len(lead):], 'vol': 'v11', 'line': [147, 152, 153], 'class': 'lead', 'note': 'лид = хвост головы «ВЭ 1.1979 г.» (@147) + съёмочная справка (@152); проза начинается с «По мотивам одноименной повести Л. Кассиля.» (@153)'}
# ── LEAD: остатки П4 (списки ролей с инициалов, оркестры/ансамбли, дубляж) ──
draft = json.load(open('work/p6_k3_leads_draft.json', encoding='utf-8'))
skip = {k for k in draft if k in SET}
for k, v in draft.items():
    if k in SET: continue
    c = int(k); b = cat[c]['annotation']
    assert b == v['lead'] + v['rest'] and b.endswith(v['rest'])
    SET[k] = {'field': 'annotation', 'before': b, 'after': v['rest'], 'vol': cat[c]['source'].split('_')[0], 'line': None, 'class': 'lead',
              'note': f"лид-остаток П4 ({'+'.join(v['rules'])}): срезан титровый блок {len(v['lead'])} зн.; остаток начинается «{v['rest'][:50]}…»"}
# ── YEAR: cat2106 «Андриеш» ──
SET['2106'] = {'field': 'year', 'before': 1955, 'after': 1954, 'vol': 'v2', 'line': 6462, 'class': 'year', 'note': 'печатная голова @6462 «2089. АНДРИЕШ. Экраниз , Киевская киностудия, цв., 6 ч., 1701 м, 1954 г , ВЭ.ЗО.У 1955 г.» — год производства 1954, каталожный 1955 = год ВЭ (вето П5-2 §3.1)'}
res = {'set': SET, 'confirm': {}}
json.dump(res, open('scripts/k3_resolution.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
from collections import Counter
print('SET', len(SET), Counter(v['class'] for v in SET.values()), 'draft leads skipped (restore приоритет):', sorted(skip))
for c in ['5542','5555','5716','5980','753','5246','3873','4951','3774','349','3773','5541']:
    v=SET[c]; print(c, v['class'], '| after:', v['after'][:110].replace('\n',' '), '…', v['after'][-40:])
